import * as path from "node:path";
import { AcpProcessClient } from "../integrations/acp/acp_process_client";
import { AcpSession, AcpSessionFactory } from "../integrations/acp/session";
import {
  ACP_CLOSE_TIMEOUT_MS,
  AcpInitializationCleanupError,
  closeAcpSession,
} from "../integrations/acp/session_lifecycle";
import { awaitBeforeDeadline, awaitWithAbort } from "../runtime/turn_deadline";
import { AcpMcpBridgeFactory } from "../integrations/acp/acp_mcp_bridge";
import { ResolvedAgentRuntimeProfile } from "../../runtime/config/contracts";
import { AgentTurnOptions } from "../runtime/agent_turn_executor";
import { AuditAgentExecutor } from "./contracts";
import { auditSystemPrompt, auditTurnPrompt } from "./prompts";
import { AuditMcpControlServer } from "./audit_mcp_control";
import { AuditSubmission, AuditToolContext, AuditToolTurnRegistry } from "./audit_tool_protocol";
export interface AcpAuditAgentExecutorOptions {
  profile: ResolvedAgentRuntimeProfile;
  workspaceRoot: string;
  sessionFactoryResolver?: (
    registry: AuditToolTurnRegistry,
    workspace: string,
  ) => AcpSessionFactory<AuditToolTurnRegistry>;
}

/** ACP + MCP 适配器；每个并行审计任务使用独立进程和独立 registry。 */
export class AcpAuditAgentExecutor implements AuditAgentExecutor {
  private nextSession = 0;
  private readonly pending = new Set<AbortController>();
  private readonly sessions = new Set<AcpSession>();
  private closed = false;
  private readonly creating = new Set<Promise<AcpSession>>();
  private readonly retiring = new Set<Promise<void>>();
  private readonly retired = new WeakMap<AcpSession, Promise<void>>();
  private readonly cleanupFailures: unknown[] = [];

  get runtimeState() {
    return {
      closed: this.closed,
      pending: this.pending.size,
      sessions: this.sessions.size,
      creating: this.creating.size,
      retiring: this.retiring.size,
    };
  }

  constructor(private readonly options: AcpAuditAgentExecutorOptions) {}

  async runTurn(
    context: AuditToolContext,
    options: AgentTurnOptions,
  ): Promise<AuditSubmission | null> {
    if (this.closed || options.timeoutMs <= 0) return null;
    const registry = new AuditToolTurnRegistry(context.locale);
    const workspace = path.join(
      this.options.workspaceRoot,
      `${String(context.taskName).replace(/[^a-zA-Z0-9_-]/g, "_")}-${++this.nextSession}`,
    );
    const factory =
      this.options.sessionFactoryResolver?.(registry, workspace) ??
      this.createProcessFactory(registry, workspace);
    if (this.closed) return null;
    let session: AcpSession | undefined;
    let primary: unknown;
    let hasPrimary = false;
    const controller = new AbortController();
    this.pending.add(controller);
    const deadlineAtMs = Date.now() + options.timeoutMs;
    const timer = setTimeout(
      () => controller.abort(new Error("audit_acp_timeout")),
      options.timeoutMs,
    );
    try {
      const sessionTask = Promise.resolve().then(() =>
        factory.createSession({
          actorId: 0,
          registry,
          initialPrompt: auditSystemPrompt(registry.locale, true),
          deadlineAtMs,
          signal: controller.signal,
        }),
      );
      this.creating.add(sessionTask);
      void sessionTask.then(
        (lateSession) => {
          this.creating.delete(sessionTask);
          if (controller.signal.aborted || this.closed)
            void this.retire(lateSession, true).catch(() => undefined);
        },
        (error) => {
          this.creating.delete(sessionTask);
          if (
            error instanceof AcpInitializationCleanupError ||
            (controller.signal.aborted && error !== controller.signal.reason)
          )
            this.cleanupFailures.push(error);
        },
      );
      session = await awaitWithAbort(sessionTask, controller.signal);
      this.sessions.add(session);
      controller.signal.throwIfAborted();
      const turn = registry.openTurn(context, session.sessionId);
      const promptTask = session.prompt(
        auditTurnPrompt(turn.turnId, context.mode, registry.locale),
      );
      return await awaitWithAbort(
        Promise.race([
          turn.result,
          promptTask.then(
            () => null,
            (error) => {
              if (!controller.signal.aborted && !hasPrimary) {
                primary = error;
                hasPrimary = true;
              }
              return null;
            },
          ),
        ]),
        controller.signal,
      );
    } catch (error) {
      primary = error;
      hasPrimary = true;
      return null;
    } finally {
      clearTimeout(timer);
      registry.closeTurn();
      this.pending.delete(controller);
      const force = controller.signal.aborted;
      controller.abort(new Error("audit_acp_turn_closed"));
      if (session) {
        this.sessions.delete(session);
        try {
          await this.retire(session, force);
        } catch (error) {
          if (hasPrimary)
            throw new AggregateError([primary, error], "audit_acp_turn_and_cleanup_failed");
          throw error;
        }
      }
    }
  }

  async close(): Promise<void> {
    this.closed = true;
    for (const controller of this.pending) {
      controller.abort(new Error("audit_acp_executor_closed"));
    }
    for (const session of this.sessions) void this.retire(session, true).catch(() => undefined);
    this.sessions.clear();
    try {
      await awaitBeforeDeadline(
        () => Promise.allSettled([...this.creating]),
        Date.now() + ACP_CLOSE_TIMEOUT_MS,
      );
    } catch (error) {
      this.cleanupFailures.push(error);
    }
    while (this.retiring.size) await Promise.all([...this.retiring]);
    const failures = this.cleanupFailures.splice(0);
    if (failures.length) throw new AggregateError(failures, "audit_acp_close_failed");
  }

  private retire(session: AcpSession, force: boolean): Promise<void> {
    const existing = this.retired.get(session);
    if (existing) return existing;
    const closing = closeAcpSession(session, force);
    this.retired.set(session, closing);
    const accounted = closing.catch((error) => {
      this.cleanupFailures.push(error);
    });
    this.retiring.add(accounted);
    void accounted.then(() => this.retiring.delete(accounted));
    return closing;
  }

  private createProcessFactory(
    registry: AuditToolTurnRegistry,
    workspace: string,
  ): AcpSessionFactory<AuditToolTurnRegistry> {
    const profile = this.options.profile;
    if (profile.kind !== "acp" || profile.provider.type !== "acp") {
      throw new Error("audit_acp_profile_required");
    }
    const extension = path.extname(__filename) === ".ts" ? ".ts" : ".js";
    const bridge: AcpMcpBridgeFactory<AuditToolTurnRegistry> = {
      serverName: "werewolf-audit",
      createControl: (turnRegistry) => new AuditMcpControlServer(turnRegistry),
      serverEntrypoint: () => path.join(__dirname, `audit_mcp_server${extension}`),
    };
    return new AcpProcessClient<AuditToolTurnRegistry>({
      command: profile.provider.command,
      args: [...(profile.provider.args ?? []), ...(profile.spawnArgs ?? [])],
      env: profile.provider.env,
      initializeTimeoutMs: profile.provider.initializeTimeoutMs,
      sessionConfigOptions: profile.provider.sessionConfigOptions,
      cwd: workspace,
      mcpBridge: bridge,
    });
  }
}

import { toolFailure } from "@ai-werewolf-arena/game-text";
import { AcpMcpServerConfig } from "../integrations/acp/acp_mcp_bridge";
import { LoopbackMcpControlServer } from "../integrations/acp/loopback_mcp_control_server";
import { AuditToolTurnRegistry } from "./audit_tool_protocol";

/** 单个审计 ACP session 的 loopback MCP 控制面。 */
export class AuditMcpControlServer {
  private readonly delegate: LoopbackMcpControlServer;

  constructor(private readonly registry: AuditToolTurnRegistry) {
    this.delegate = new LoopbackMcpControlServer({
      serverName: "werewolf-audit",
      controlUrlEnvironmentName: "AUDIT_MCP_CONTROL_URL",
      tokenEnvironmentName: "AUDIT_MCP_TOKEN",
      sessionNotReadyError: "session_not_ready",
      invalidRequestPrefix: "invalid_audit_mcp_request",
      locale: registry.locale,
      dispatch: (sessionId, tool, args) => this.dispatch(sessionId, tool, args),
    });
  }

  async start(command: string, args: string[]): Promise<AcpMcpServerConfig> {
    return this.delegate.start(command, args);
  }

  bindSession(sessionId: string): void {
    this.delegate.bindSession(sessionId);
  }

  async close(options: { force?: boolean } = {}): Promise<void> {
    await this.delegate.close(options);
  }

  private dispatch(sessionId: string, tool: unknown, args: unknown): unknown {
    if (tool === "get_audit_schema") return this.registry.getSchema();
    if (tool === "get_audit_context") return this.registry.getContext(sessionId, args);
    if (tool === "submit_audit_findings") return this.registry.submitFindings(sessionId, args);
    if (tool === "submit_audit_summary") return this.registry.submitSummary(sessionId, args);
    return toolFailure(this.registry.locale, "unknown_mcp_tool");
  }
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { auditToolProtocol } from "./audit_tool_protocol";
import { taskLocale } from "../integrations/acp/task_locale";

const endpoint = process.env.AUDIT_MCP_CONTROL_URL;
const token = process.env.AUDIT_MCP_TOKEN;

async function invoke(
  tool: string,
  args: Record<string, unknown> = {},
): Promise<Record<string, unknown>> {
  if (!endpoint || !token) throw new Error("audit_mcp_control_environment_missing");
  const response = await fetch(`${endpoint}/invoke`, {
    method: "POST",
    headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
    body: JSON.stringify({ tool, arguments: args }),
  });
  return (await response.json()) as Record<string, unknown>;
}

function result(value: Record<string, unknown>) {
  return {
    content: [{ type: "text" as const, text: JSON.stringify(value) }],
    structuredContent: value,
    ...(value.ok === false ? { isError: true } : {}),
  };
}

async function main(): Promise<void> {
  const protocol = auditToolProtocol(taskLocale(process.env));
  const server = new McpServer({ name: "werewolf-audit", version: "1.0.0" });
  server.registerTool(
    "get_audit_schema",
    {
      description: protocol.descriptions.get_audit_schema,
      inputSchema: protocol.inputs.get_audit_schema.shape,
    },
    async () => result(await invoke("get_audit_schema")),
  );
  server.registerTool(
    "get_audit_context",
    {
      description: protocol.descriptions.get_audit_context,
      inputSchema: protocol.inputs.get_audit_context.shape,
    },
    async (args) => result(await invoke("get_audit_context", args)),
  );
  server.registerTool(
    "submit_audit_findings",
    {
      description: protocol.descriptions.submit_audit_findings,
      inputSchema: protocol.inputs.submit_audit_findings.shape,
    },
    async (args) => result(await invoke("submit_audit_findings", args)),
  );
  server.registerTool(
    "submit_audit_summary",
    {
      description: protocol.descriptions.submit_audit_summary,
      inputSchema: protocol.inputs.submit_audit_summary.shape,
    },
    async (args) => result(await invoke("submit_audit_summary", args)),
  );
  await server.connect(new StdioServerTransport());
}

void main();

/**
 * 负责 SDK／ACP 审计工具的 schema、单回合上下文与提交状态。输入为会话／turn ID、审计模式及 payload，输出为受控查询或审计发现／摘要回执。
 * 本注册表唯一持有 pending 回合，成功提交先移除再完成 Promise；证据序号仅限当前上下文，不能代替游戏行动权限。
 */
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { z } from "zod";
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { isLocale } from "@ai-werewolf-arena/game-contract";
import { ToolSchema } from "../integrations/llm/transport";

export type AuditSeverity = "low" | "medium" | "high" | "critical";
export type AuditCategory = "flow" | "rule" | "state" | "logging" | "other";

export interface AuditFinding {
  severity: AuditSeverity;
  category: AuditCategory;
  message: string;
  evidence: number[];
  source: string;
}

export interface AuditInspectionResult {
  kind: "findings";
  agent: string;
  findings: AuditFinding[];
  notes: string[];
  missing_info: string[];
}

export interface AuditSummaryResult {
  kind: "summary";
  markdown: string;
}

export type AuditSubmission = AuditInspectionResult | AuditSummaryResult;

export interface AuditToolContext {
  locale?: Locale;
  mode: "inspect" | "summarize";
  taskName: string;
  source: string;
  payload: Record<string, unknown>;
}

export function auditToolProtocol(locale: Locale = "zh-CN") {
  const schemaError = text(locale, "error.schema_input");
  const turnId = z
    .string({ error: schemaError })
    .min(1, { error: schemaError })
    .describe(text(locale, "schema.turn_id"));
  const findingInput = z.object(
    {
      severity: z
        .enum(["low", "medium", "high", "critical"], { error: schemaError })
        .describe(text(locale, "schema.severity")),
      category: z
        .enum(["flow", "rule", "state", "logging", "other"], { error: schemaError })
        .describe(text(locale, "schema.category")),
      message: z
        .string({ error: schemaError })
        .min(1, { error: schemaError })
        .max(300, { error: schemaError })
        .describe(text(locale, "schema.audit.finding_message")),
      evidence: z
        .array(
          z
            .number({ error: schemaError })
            .int({ error: schemaError })
            .positive({ error: schemaError }),
          { error: schemaError },
        )
        .max(20, { error: schemaError })
        .describe(text(locale, "schema.audit.evidence")),
    },
    { error: schemaError },
  );
  const inputs = {
    get_audit_schema: z.object({}, { error: schemaError }),
    get_audit_context: z.object({ turn_id: turnId }, { error: schemaError }),
    submit_audit_findings: z.object(
      {
        turn_id: turnId,
        findings: z
          .array(findingInput, { error: schemaError })
          .max(5, { error: schemaError })
          .describe(text(locale, "schema.audit.finding_list")),
        notes: z
          .array(
            z
              .string({ error: schemaError })
              .min(1, { error: schemaError })
              .max(240, { error: schemaError })
              .describe(text(locale, "schema.audit.note_item")),
            { error: schemaError },
          )
          .max(3, { error: schemaError })
          .default([])
          .describe(text(locale, "schema.audit.notes")),
        missing_info: z
          .array(
            z
              .string({ error: schemaError })
              .min(1, { error: schemaError })
              .max(240, { error: schemaError })
              .describe(text(locale, "schema.audit.missing_item")),
            { error: schemaError },
          )
          .max(3, { error: schemaError })
          .default([])
          .describe(text(locale, "schema.audit.missing_info")),
      },
      { error: schemaError },
    ),
    submit_audit_summary: z.object(
      {
        turn_id: turnId,
        markdown: z
          .string({ error: schemaError })
          .min(1, { error: schemaError })
          .max(12_000, { error: schemaError })
          .describe(text(locale, "schema.audit.markdown")),
      },
      { error: schemaError },
    ),
  };
  const descriptions = {
    get_audit_schema: text(locale, "schema.audit.query"),
    get_audit_context: text(locale, "schema.audit.context"),
    submit_audit_findings: text(locale, "schema.audit.findings"),
    submit_audit_summary: text(locale, "schema.audit.summary"),
  };
  const schema = {
    protocol_version: "1",
    tools: {
      get_audit_schema: text(locale, "schema.audit.static_query"),
      get_audit_context: text(locale, "schema.audit.static_context"),
      submit_audit_findings: text(locale, "schema.audit.static_findings"),
      submit_audit_summary: text(locale, "schema.audit.static_summary"),
    },
  };
  const specs: ToolSchema[] = (Object.keys(inputs) as Array<keyof typeof inputs>).map((name) => ({
    name,
    description: descriptions[name],
    parameters: z.toJSONSchema(inputs[name], { io: "input", target: "draft-7" }) as Record<
      string,
      unknown
    >,
  }));
  return { inputs, descriptions, schema, specs };
}

const defaultProtocol = auditToolProtocol();
export const getAuditContextInput = defaultProtocol.inputs.get_audit_context;
export const getAuditSchemaInput = defaultProtocol.inputs.get_audit_schema;
export const submitAuditFindingsInput = defaultProtocol.inputs.submit_audit_findings;
export const submitAuditSummaryInput = defaultProtocol.inputs.submit_audit_summary;
export const AUDIT_TOOL_SCHEMA = defaultProtocol.schema;
export const AUDIT_TOOL_SPECS = defaultProtocol.specs;

export type AuditToolResult =
  | { ok: true; accepted?: true; context?: Record<string, unknown> }
  | { ok: false; error: string; message: string };

interface PendingAuditTurn {
  sessionId: string;
  turnId: string;
  context: AuditToolContext;
  result: Promise<AuditSubmission | null>;
  resolve: (value: AuditSubmission | null) => void;
}

/** SDK 与 ACP 共用的单回合上下文隔离、Schema 校验和提交状态机。 */
export class AuditToolTurnRegistry {
  private pending: PendingAuditTurn | null = null;
  private nextTurn = 0;

  constructor(readonly locale: Locale = "zh-CN") {
    if (!isLocale(locale)) throw new Error("audit_task_locale_invalid");
  }

  openTurn(
    context: AuditToolContext,
    sessionId: string,
  ): {
    turnId: string;
    result: Promise<AuditSubmission | null>;
  } {
    if (this.pending) throw new Error("audit_turn_already_open");
    const turnId = `a${++this.nextTurn}`;
    let resolve!: (value: AuditSubmission | null) => void;
    const result = new Promise<AuditSubmission | null>((done) => {
      resolve = done;
    });
    this.pending = { sessionId, turnId, context, result, resolve };
    return { turnId, result };
  }

  getSchema(): typeof AUDIT_TOOL_SCHEMA {
    return auditToolProtocol(this.locale).schema;
  }

  getContext(sessionId: string, input: unknown): AuditToolResult {
    const parsed = getAuditContextInput.safeParse(input);
    if (!parsed.success) return toolFailure(this.locale, "invalid_get_audit_context_arguments");
    const pending = this.getPending(sessionId, parsed.data.turn_id);
    if (!pending) return toolFailure(this.locale, "audit_turn_not_open_or_session_invalid");
    return {
      ok: true,
      context: {
        mode: pending.context.mode,
        task_name: pending.context.taskName,
        source: pending.context.source,
        payload: pending.context.payload,
      },
    };
  }

  submitFindings(sessionId: string, input: unknown): AuditToolResult {
    const parsed = submitAuditFindingsInput.safeParse(input);
    if (!parsed.success) return toolFailure(this.locale, "invalid_submit_audit_findings_arguments");
    const pending = this.getPending(sessionId, parsed.data.turn_id);
    if (!pending) return toolFailure(this.locale, "audit_turn_not_open_or_session_invalid");
    if (pending.context.mode !== "inspect") {
      return toolFailure(this.locale, "audit_tool_not_allowed_in_this_mode");
    }
    const visibleEvidence = collectVisibleEvidenceSeqs(pending.context.payload);
    if (
      parsed.data.findings.some((finding) =>
        finding.evidence.some((seq) => !visibleEvidence.has(seq)),
      )
    ) {
      return toolFailure(this.locale, "audit_evidence_not_visible_in_current_context");
    }
    this.pending = null;
    pending.resolve({
      kind: "findings",
      agent: pending.context.taskName,
      findings: parsed.data.findings.map((item) => ({
        ...item,
        source: pending.context.source,
      })),
      notes: parsed.data.notes,
      missing_info: parsed.data.missing_info,
    });
    return { ok: true, accepted: true };
  }

  submitSummary(sessionId: string, input: unknown): AuditToolResult {
    const parsed = submitAuditSummaryInput.safeParse(input);
    if (!parsed.success) return toolFailure(this.locale, "invalid_submit_audit_summary_arguments");
    const pending = this.getPending(sessionId, parsed.data.turn_id);
    if (!pending) return toolFailure(this.locale, "audit_turn_not_open_or_session_invalid");
    if (pending.context.mode !== "summarize") {
      return toolFailure(this.locale, "audit_tool_not_allowed_in_this_mode");
    }
    this.pending = null;
    pending.resolve({ kind: "summary", markdown: parsed.data.markdown.trim() });
    return { ok: true, accepted: true };
  }

  closeTurn(): void {
    const pending = this.pending;
    this.pending = null;
    pending?.resolve(null);
  }

  private getPending(sessionId: string, turnId: string): PendingAuditTurn | null {
    return this.pending?.sessionId === sessionId && this.pending.turnId === turnId
      ? this.pending
      : null;
  }
}

function collectVisibleEvidenceSeqs(value: unknown): Set<number> {
  const out = new Set<number>();
  const visit = (current: unknown, key?: string): void => {
    if (typeof current === "number" && Number.isInteger(current) && current > 0) {
      if (key === "seq" || key === "evidence" || key === "evidence_event_seq") out.add(current);
      return;
    }
    if (Array.isArray(current)) {
      for (const item of current) visit(item, key);
      return;
    }
    if (!current || typeof current !== "object") return;
    for (const [childKey, child] of Object.entries(current as Record<string, unknown>)) {
      visit(child, childKey);
    }
  };
  visit(value);
  return out;
}

import { AgentTurnExecutor } from "../runtime/agent_turn_executor";
import { AuditSubmission, AuditToolContext } from "./audit_tool_protocol";

export type AuditAgentExecutor = AgentTurnExecutor<AuditToolContext, AuditSubmission>;

import { AiSdkClient } from "../integrations/llm/ai_sdk_client";
import { ResolvedAgentRuntimeProfile } from "../../runtime/config/contracts";
import { AuditAgentExecutor } from "./contracts";
import { SdkAuditAgentExecutor } from "./sdk_audit_runner";
import { AcpAuditAgentExecutor } from "./acp_audit_runner";
/** Abstract Factory：调用方只提供统一 agent profile，不判断 SDK/ACP transport。 */
export function createAuditAgentExecutor(options: {
  profile: ResolvedAgentRuntimeProfile;
  workspaceRoot: string;
}): AuditAgentExecutor | null {
  const { profile } = options;
  if (profile.kind === "acp" && profile.provider.type === "acp") {
    return new AcpAuditAgentExecutor({
      profile,
      workspaceRoot: options.workspaceRoot,
    });
  }
  if (
    profile.kind !== "llm" ||
    profile.provider.type === "acp" ||
    !profile.provider.apiKey ||
    !profile.model
  ) {
    return null;
  }
  return new SdkAuditAgentExecutor(
    new AiSdkClient({
      providerType: profile.provider.type,
      providerName: profile.providerName,
      apiKey: profile.provider.apiKey,
      model: profile.model,
      baseURL: profile.provider.baseURL,
      userAgent: profile.provider.userAgent,
      temperature:
        profile.temperature ??
        (profile.reasoningEffort || profile.thinkingEnabled ? undefined : 0.1),
      maxTokens: profile.maxTokens ?? 1200,
      reasoningEffort: profile.reasoningEffort,
      thinkingEnabled: profile.thinkingEnabled ?? false,
    }),
  );
}

export * from "./contracts";
export * from "./executor_factory";
export * from "./sdk_audit_runner";
export * from "./acp_audit_runner";
export * from "./audit_mcp_control";
export * from "./audit_tool_protocol";

import { auditHeadings, text, type Locale } from "@ai-werewolf-arena/game-text";
import type { AuditToolContext } from "./audit_tool_protocol";

/** One semantic audit policy; transports only choose whether initialization may use tools. */
export function auditSystemPrompt(locale: Locale = "zh-CN", initializing = false): string {
  return [
    text(locale, "audit.prompt.identity"),
    text(locale, "audit.prompt.language"),
    text(locale, "audit.prompt.claims"),
    text(locale, "audit.prompt.boundaries"),
    ...(initializing
      ? [text(locale, "audit.prompt.acp.init")]
      : [text(locale, "audit.prompt.read"), text(locale, "audit.prompt.submit")]),
    text(locale, "audit.prompt.evidence"),
    text(locale, "audit.prompt.outcome"),
  ].join("\n");
}

export function auditTurnPrompt(
  turnId: string,
  mode: AuditToolContext["mode"],
  locale: Locale = "zh-CN",
): string {
  const headings = auditHeadings(locale);
  const directive =
    mode === "inspect"
      ? text(locale, "audit.prompt.inspect")
      : text(locale, "audit.prompt.summary", {
          session: headings.session,
          stats: headings.stats,
          findings: headings.findings,
          todo: headings.todo,
          conclusion: headings.conclusion,
          pipeline: headings.pipeline,
          none: text(locale, "common.none"),
        });
  return [
    text(locale, "audit.prompt.turn", { turn: turnId }),
    text(locale, "audit.prompt.mode", { mode }),
    text(locale, "audit.prompt.use_tools"),
    directive,
  ].join("\n");
}

import { toolFailure } from "@ai-werewolf-arena/game-text";
import { ToolLoopClient } from "../integrations/llm/transport";
import { AgentTurnOptions } from "../runtime/agent_turn_executor";
import { AuditAgentExecutor } from "./contracts";
import { auditSystemPrompt, auditTurnPrompt } from "./prompts";
import {
  auditToolProtocol,
  AuditSubmission,
  AuditToolContext,
  AuditToolResult,
  AuditToolTurnRegistry,
} from "./audit_tool_protocol";
function asToolRecord(result: AuditToolResult | object): Record<string, unknown> {
  return result as Record<string, unknown>;
}

/** AI SDK function-tools 适配器。 */
export class SdkAuditAgentExecutor implements AuditAgentExecutor {
  private nextSession = 0;

  constructor(private readonly client: ToolLoopClient) {}

  async runTurn(
    context: AuditToolContext,
    options: AgentTurnOptions,
  ): Promise<AuditSubmission | null> {
    const registry = new AuditToolTurnRegistry(context.locale);
    const protocol = auditToolProtocol(registry.locale);
    const sessionId = `sdk-audit-${++this.nextSession}`;
    const turn = registry.openTurn(context, sessionId);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.timeoutMs);
    try {
      const result = await this.client.runToolLoop<AuditSubmission>(
        [
          { role: "system", content: auditSystemPrompt(registry.locale) },
          { role: "user", content: auditTurnPrompt(turn.turnId, context.mode, registry.locale) },
        ],
        protocol.specs,
        {
          onToolCall: async (invocation) => {
            if (invocation.name === "get_audit_schema") {
              return { toolResult: asToolRecord(registry.getSchema()) };
            }
            if (invocation.name === "get_audit_context") {
              return { toolResult: asToolRecord(registry.getContext(sessionId, invocation.args)) };
            }
            if (invocation.name === "submit_audit_findings") {
              const toolResult = registry.submitFindings(sessionId, invocation.args);
              const finalAction = toolResult.ok ? await turn.result : undefined;
              return {
                toolResult: asToolRecord(toolResult),
                ...(finalAction ? { finalAction, stop: true } : {}),
              };
            }
            if (invocation.name === "submit_audit_summary") {
              const toolResult = registry.submitSummary(sessionId, invocation.args);
              const finalAction = toolResult.ok ? await turn.result : undefined;
              return {
                toolResult: asToolRecord(toolResult),
                ...(finalAction ? { finalAction, stop: true } : {}),
              };
            }
            return { toolResult: toolFailure(registry.locale, "unknown_audit_tool") };
          },
        },
        { signal: controller.signal, maxSteps: 6, toolChoice: "required" },
      );
      return result.finalAction;
    } catch {
      return null;
    } finally {
      clearTimeout(timer);
      registry.closeTurn();
    }
  }

  async close(): Promise<void> {}
}
